#!/bin/bash
# Generated by OrchestKit Claude Plugin
# Created: 2026-09-11

# Test: Lab manifest fragments merge without conflict (#4049, #4185)
#
# Every PR that ships a playground used to edit one shared file,
# docs/site/lab-manifest.json, plus the whole-file aggregate lab-data.ts, so
# any two concurrent PRs conflicted on rebase (five in one lane, 2026-09-10)
# and the obvious --ours/--theirs resolution dropped an entry while the count
# still looked right. The #4049 shape fixed the fragments: one file per entry
# under docs/site/lab-manifest/<slug>.json. The #4185 shape removes the last
# conflict surface: lab-data.ts is NOT committed anymore. It is regenerated by
# docs/site's prebuild/predev/pretest steps and the root build (phase 7), from
# the fragments. The union merge driver from #4184 is gone: there is no
# committed aggregate to merge, so there is nothing to conflict on and nothing
# to hand-resolve.
#
# This suite is the scripted control:
#   1. Two fixture branches each add a DIFFERENT page + fragment and merge.
#      `git merge` completes with no conflict and both fragment sets are
#      intact. The on-disk aggregate is stale after the merge, and --check
#      says exactly which slug it lacks; one generator run restores the full
#      set and --check passes. The aggregate is a build artifact, not a merge
#      product.
#   2. Adjacent slugs (the residual textual conflict of the committed
#      aggregate) no longer conflict at all: the aggregate is not in git.
#   3. The build-time generation contract (#4185):
#      a. with lab-data.ts deleted, the generator recreates it and --check
#         passes;
#      b. every fragment slug appears in the generated file (a SET compare,
#         not a line count);
#      c. with lab-data.ts deleted and the generator NOT run, --check exits
#         non-zero with the absence message (absent is never treated as
#         empty, never passed);
#      d. in the real repo, git check-ignore ignores the aggregate and the
#         aggregate is not tracked in the index.
#   4. Fault arms, each through the SAME oracle CI runs (`--check`): a stale
#      aggregate that dropped an entry (count unchanged), an aggregate entry
#      with no fragment, an orphan public/lab copy, a resurrected legacy
#      lab-manifest.json, a fragment whose slug does not match its file name,
#      and an unknown key. Every one must fail; the clean tree must pass.
#
# Every grep runs against a FILE, never a pipe or here-string (#603, bash 3.2
# and 5.3 here-string rules). Nested git runs with the GIT_* environment
# scrubbed: a hook-inherited GIT_INDEX_FILE once wiped the real index from a
# fixture commit (2026-09-06).

set -euo pipefail

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
REPO_ROOT="$(cd "$SCRIPT_DIR/../.." && pwd)"
TOOL="$REPO_ROOT/docs/site/scripts/lab-manifest.mjs"

FAILED=0
CHECKED=0

if [[ ! -f "$TOOL" ]]; then
  echo "FAIL: generator missing: $TOOL"
  exit 1
fi

WORK="$(mktemp -d "${TMPDIR:-/tmp}/lab-fragments.XXXXXX")"
trap 'rm -rf "$WORK"' EXIT
OUT="$WORK/out.txt"

ok()  { CHECKED=$((CHECKED+1)); echo "PASS: $1"; }
bad() { CHECKED=$((CHECKED+1)); FAILED=$((FAILED+1)); echo "FAIL: $1"; }

# git with the caller's GIT_* scrubbed and a fixed identity (no signing).
g() { # <dir> <args...>
  local d="$1"; shift
  env -u GIT_DIR -u GIT_WORK_TREE -u GIT_INDEX_FILE -u GIT_PREFIX -u GIT_OBJECT_DIRECTORY \
    GIT_CONFIG_GLOBAL=/dev/null GIT_CONFIG_SYSTEM=/dev/null \
    GIT_AUTHOR_NAME=t GIT_AUTHOR_EMAIL=t@t GIT_COMMITTER_NAME=t GIT_COMMITTER_EMAIL=t@t \
    git -C "$d" -c commit.gpgsign=false "$@"
}

gen()   { node "$TOOL" --repo "$1" >"$OUT" 2>&1; }
check() { node "$TOOL" --check --repo "$1" >"$OUT" 2>&1; }

# add_page <repo> <slug> <date>: page + fragment, as a PR author would.
add_page() {
  local d="$1" slug="$2" date="$3"
  mkdir -p "$d/docs/feat--$slug"
  printf '<!doctype html><title>%s</title><meta name="description" content="about %s"><p>%s' "$slug" "$slug" "$slug" \
    > "$d/docs/feat--$slug/page.html"
  printf '{"slug":"%s","source":"docs/feat--%s/page.html","tags":["t"],"date":"%s"}\n' "$slug" "$slug" "$date" \
    > "$d/docs/site/lab-manifest/$slug.json"
}

# Slugs present in a lab-data.ts, one per line, into a file.
slugs_of() { # <repo> <outfile>
  node -e '
    const t = require("fs").readFileSync(process.argv[1], "utf8");
    for (const l of t.split("\n")) { const m = l.match(/^  \{"slug":"([^"]+)"/); if (m) console.log(m[1]); }
  ' "$1/docs/site/lib/generated/lab-data.ts" > "$2"
}

count_lines() { awk 'NF{n++} END{print n+0}' "$1"; }

# A fresh copy of the clean merged tree A, for any arm that needs one. Defined
# early: the build-time contract cases (section 3) use it too.
fresh() { # <name> -> path
  local d="$WORK/arm-$1"
  rm -rf "$d"; mkdir -p "$d"
  cp -R "$A/docs" "$d/docs"
  echo "$d"
}

# Base repo: two entries whose slugs leave gaps on both sides and between.
# The fixture mirrors the repo's real rule (#4185): the aggregate is not
# committed, so `git add -A` must skip it.
BASE="$WORK/base"
mkdir -p "$BASE/docs/site/lab-manifest"
printf '# mirror of docs/site/.gitignore (#4185)\nlib/generated/lab-data.ts\n' > "$BASE/docs/site/.gitignore"
add_page "$BASE" "bbb-existing" "2026-09-01"
add_page "$BASE" "mmm-existing" "2026-09-02"
if ! gen "$BASE"; then cat "$OUT"; echo "FAIL: base generate"; exit 1; fi
g "$BASE" init -q -b main
g "$BASE" add -A
g "$BASE" commit -qm base
if g "$BASE" ls-files --error-unmatch docs/site/lib/generated/lab-data.ts >/dev/null 2>&1; then
  bad "base: fixture committed the generated aggregate (ignore rule not honored)"
else
  ok "base: fixture leaves the aggregate uncommitted (ignore rule honored)"
fi

# ---------------------------------------------------------------- 1. disjoint
# Branch A adds "aaa-from-a" (sorts before bbb), branch B adds "zzz-from-b"
# (sorts after mmm): different fragment files, different public/lab copies.
A="$WORK/a"; B="$WORK/b"
g "$BASE" worktree add -q "$A" -b pr-a
g "$BASE" worktree add -q "$B" -b pr-b
add_page "$A" "aaa-from-a" "2026-09-11"; gen "$A"; g "$A" add -A; g "$A" commit -qm "a: page"
add_page "$B" "zzz-from-b" "2026-09-11"; gen "$B"; g "$B" add -A; g "$B" commit -qm "b: page"

if g "$A" merge -q --no-edit pr-b >"$OUT" 2>&1; then
  ok "disjoint: two additions merge with no conflict (the aggregate is not in git)"
else
  bad "disjoint: merge reported a conflict"; cat "$OUT"
fi
g "$A" diff --name-only --diff-filter=U > "$WORK/a-unmerged.txt"
if [[ "$(count_lines "$WORK/a-unmerged.txt")" == "0" ]]; then
  ok "disjoint: no unmerged paths after the merge"
else
  bad "disjoint: unmerged paths: $(tr '\n' ' ' < "$WORK/a-unmerged.txt")"
fi
# The on-disk aggregate is A's pre-merge copy: stale, and the oracle must say
# which slug the merge has not generated yet.
if check "$A"; then
  bad "disjoint: --check passed on the stale pre-regeneration aggregate (it must flag the gap)"
else
  if grep -Fq 'lacks "zzz-from-b"' "$OUT"; then
    ok "disjoint: --check names the slug the merge has not generated yet"
  else
    bad "disjoint: --check failed without naming the ungenerated slug"; cat "$OUT"
  fi
fi
gen "$A"
if check "$A"; then
  ok "disjoint: after one generator run, the merged tree passes --check"
else
  bad "disjoint: regenerated merged tree fails --check"; cat "$OUT"
fi
slugs_of "$A" "$WORK/a-slugs.txt"
for s in aaa-from-a bbb-existing mmm-existing zzz-from-b; do
  if grep -Fxq "$s" "$WORK/a-slugs.txt"; then
    ok "disjoint: merged lab-data.ts carries $s"
  else
    bad "disjoint: merged lab-data.ts lacks $s"
  fi
done
if [[ "$(count_lines "$WORK/a-slugs.txt")" == "4" ]]; then
  ok "disjoint: exactly 4 entries after the merge"
else
  bad "disjoint: expected 4 entries, got $(count_lines "$WORK/a-slugs.txt")"
fi
if [[ -f "$A/docs/site/public/lab/aaa-from-a.html" && -f "$A/docs/site/public/lab/zzz-from-b.html" ]]; then
  ok "disjoint: both public/lab copies present after the merge"
else
  bad "disjoint: a public/lab copy is missing after the merge"
fi

# ----------------------------------------------------- 2. adjacent slugs
# "ccc-1" and "ccc-2" both sort into the gap between bbb and mmm. On the old
# committed aggregate this was the residual textual conflict that needed the
# take-either-side-and-regenerate rule (#4181, #4184). With the aggregate
# uncommitted (#4185) the merge cannot touch it: zero conflicts, and one
# generator run yields the complete set.
C="$WORK/c"; D="$WORK/d"
g "$BASE" worktree add -q "$C" -b pr-c
g "$BASE" worktree add -q "$D" -b pr-d
add_page "$C" "ccc-1" "2026-09-11"; gen "$C"; g "$C" add -A; g "$C" commit -qm "c: page"
add_page "$D" "ccc-2" "2026-09-11"; gen "$D"; g "$D" add -A; g "$D" commit -qm "d: page"
if g "$C" merge -q --no-edit pr-d >"$OUT" 2>&1; then
  ok "adjacent: two adjacent-slug additions merge with no conflict"
else
  bad "adjacent: merge reported a conflict (the aggregate must not be in git)"; cat "$OUT"
fi
g "$C" diff --name-only --diff-filter=U > "$WORK/c-unmerged.txt"
if [[ "$(count_lines "$WORK/c-unmerged.txt")" == "0" ]]; then
  ok "adjacent: no unmerged paths (the old lab-data.ts conflict is gone)"
else
  bad "adjacent: unmerged paths: $(tr '\n' ' ' < "$WORK/c-unmerged.txt")"
fi
gen "$C"
if check "$C"; then
  ok "adjacent: regenerated tree passes --check with the full set"
else
  bad "adjacent: regenerated tree fails --check"; cat "$OUT"
fi
slugs_of "$C" "$WORK/c-slugs.txt"
if grep -Fxq "ccc-1" "$WORK/c-slugs.txt" && grep -Fxq "ccc-2" "$WORK/c-slugs.txt"; then
  ok "adjacent: both entries present after regenerate"
else
  bad "adjacent: an entry is missing after regenerate"
fi

# ------------------------------------------- 3. build-time contract (#4185)
# The aggregate is a build artifact. Absent must never pass; the generator
# must rebuild it from nothing; the generated set must cover every fragment.

# a. With lab-data.ts deleted, the generator recreates it and --check passes.
d="$(fresh gen-recreates)"
rm "$d/docs/site/lib/generated/lab-data.ts"
if ! gen "$d"; then
  bad "a: generator failed on a tree without lab-data.ts"; cat "$OUT"
else
  if [[ -f "$d/docs/site/lib/generated/lab-data.ts" ]] && check "$d"; then
    ok "a: generator recreated a deleted lab-data.ts and --check passes"
  else
    bad "a: lab-data.ts missing or --check failed after regeneration"; cat "$OUT"
  fi
fi

# b. Every fragment slug appears in the generated file: SET compare, not a
#    line count (a count passes even when one entry replaced another).
d="$(fresh set-coverage)"
if ! gen "$d"; then cat "$OUT"; echo "FAIL: set-coverage generate"; exit 1; fi
ls "$d/docs/site/lab-manifest" | sed 's/\.json$//' | sort > "$WORK/fragment-slugs.txt"
slugs_of "$d" "$WORK/generated-slugs.txt"
sort -o "$WORK/generated-slugs.txt" "$WORK/generated-slugs.txt"
if diff -u "$WORK/fragment-slugs.txt" "$WORK/generated-slugs.txt" > "$WORK/set-diff.txt"; then
  ok "b: generated lab-data.ts covers every fragment slug exactly (set compare, $(count_lines "$WORK/fragment-slugs.txt") slugs)"
else
  bad "b: fragment slugs and generated slugs differ"; cat "$WORK/set-diff.txt"
fi

# c. lab-data.ts deleted and the generator NOT run: --check must exit
#    non-zero with the absence message. Absent is never empty, never passed.
d="$(fresh absent-fails)"
rm "$d/docs/site/lib/generated/lab-data.ts"
if check "$d"; then
  bad "c: --check passed with lab-data.ts absent (absent must fail)"
else
  if grep -Fq "is absent" "$OUT" && grep -Fqi "run the generator first" "$OUT"; then
    ok "c: --check fails on an absent aggregate and points at the generator"
  else
    bad "c: --check failed without the absence message"; cat "$OUT"
  fi
fi

# d. In the REAL repo the aggregate is gitignored and not tracked.
if git -C "$REPO_ROOT" check-ignore -q docs/site/lib/generated/lab-data.ts; then
  ok "d: git check-ignore ignores docs/site/lib/generated/lab-data.ts"
else
  bad "d: docs/site/lib/generated/lab-data.ts is not gitignored"
fi
if git -C "$REPO_ROOT" ls-files --error-unmatch docs/site/lib/generated/lab-data.ts >/dev/null 2>&1; then
  bad "d: the aggregate is still tracked in the index"
else
  ok "d: the aggregate is not tracked in the index"
fi

# --------------------------------------------------------------- 4. fault arms
# Each arm starts from a fresh copy of the clean merged tree A, breaks one
# invariant, and must fail --check. The control (unbroken copy) must pass.

d="$(fresh control)"
if check "$d"; then ok "control: clean tree passes --check"; else bad "control: clean tree fails --check"; cat "$OUT"; fi

# Stale aggregate: an entry dropped AND another added by hand so the COUNT is
# unchanged. This is the exact --theirs loss the original issue described.
d="$(fresh stale)"
node -e '
  const fs = require("fs"); const f = process.argv[1];
  const t = fs.readFileSync(f, "utf8").split("\n");
  const i = t.findIndex((l) => l.startsWith("  {\"slug\":\"zzz-from-b\""));
  t[i] = t[i].replace("zzz-from-b", "zzz-hand-edit");
  fs.writeFileSync(f, t.join("\n"));
' "$d/docs/site/lib/generated/lab-data.ts"
if check "$d"; then
  bad "stale: --check passed on an aggregate with one entry swapped (count unchanged)"
else
  if grep -Fq 'lacks "zzz-from-b"' "$OUT" && grep -Fq 'carries "zzz-hand-edit"' "$OUT"; then
    ok "stale: --check names both the dropped and the undeclared entry"
  else
    bad "stale: --check failed without naming the swap"; cat "$OUT"
  fi
fi

d="$(fresh orphan-copy)"
printf '<p>' > "$d/docs/site/public/lab/ghost.html"
if check "$d"; then bad "orphan-copy: --check passed with a public/lab file no fragment declares"; else
  if grep -Fq "ghost.html has no fragment" "$OUT"; then ok "orphan-copy: --check names the orphan copy"; else bad "orphan-copy: wrong message"; cat "$OUT"; fi
fi

d="$(fresh legacy)"
printf '{"entries":[]}' > "$d/docs/site/lab-manifest.json"
if check "$d"; then bad "legacy: --check passed with lab-manifest.json resurrected"; else
  if grep -Fq "lab-manifest.json exists" "$OUT"; then ok "legacy: --check refuses a resurrected lab-manifest.json"; else bad "legacy: wrong message"; cat "$OUT"; fi
fi

d="$(fresh slug-mismatch)"
printf '{"slug":"other","source":"docs/feat--aaa-from-a/page.html","date":"2026-09-11"}' > "$d/docs/site/lab-manifest/aaa-from-a.json"
if check "$d"; then bad "slug-mismatch: --check passed with slug != file name"; else
  if grep -Fq '"slug" must equal the file name stem' "$OUT"; then ok "slug-mismatch: --check names the mismatch"; else bad "slug-mismatch: wrong message"; cat "$OUT"; fi
fi

d="$(fresh unknown-key)"
printf '{"slug":"aaa-from-a","source":"docs/feat--aaa-from-a/page.html","date":"2026-09-11","tag":["x"]}' > "$d/docs/site/lab-manifest/aaa-from-a.json"
if check "$d"; then bad "unknown-key: --check passed with a misspelled key"; else
  if grep -Fq 'unknown key "tag"' "$OUT"; then ok "unknown-key: --check names the key"; else bad "unknown-key: wrong message"; cat "$OUT"; fi
fi

d="$(fresh removed-fragment)"
rm "$d/docs/site/lab-manifest/zzz-from-b.json"
if check "$d"; then bad "removed-fragment: --check passed with a fragment gone but aggregate and copy kept"; else
  if grep -Fq 'carries "zzz-from-b" but no fragment' "$OUT" && grep -Fq "zzz-from-b.html has no fragment" "$OUT"; then
    ok "removed-fragment: --check names the surviving aggregate entry and copy"
  else
    bad "removed-fragment: wrong message"; cat "$OUT"
  fi
fi
# ...and a rebuild cleans both up: the copy is deleted, the entry is gone.
gen "$d"
if check "$d" && [[ ! -f "$d/docs/site/public/lab/zzz-from-b.html" ]]; then
  ok "removed-fragment: regenerate deletes the orphan copy and passes --check"
else
  bad "removed-fragment: regenerate left the tree inconsistent"; cat "$OUT"
fi

# The CLI must run when invoked through a SYMLINKED path. The main-module
# guard once compared path.resolve(argv[1]) to the realpath'd module URL, so
# on macOS (/tmp -> /private/tmp) the CLI never ran and exited 0 with no
# output: a fail-open oracle (review of #4064). Both arms here go through a
# symlinked directory; the drifted tree is the removed-fragment shape.
LINK="$WORK/link"
ln -s "$REPO_ROOT" "$LINK"
TOOL_VIA_LINK="$LINK/docs/site/scripts/lab-manifest.mjs"
rc=0; node "$TOOL_VIA_LINK" --bogus >"$OUT" 2>&1 || rc=$?
if [[ "$rc" == "2" ]] && grep -Fq "unknown argument: --bogus" "$OUT"; then
  ok "symlink: --bogus through a symlinked path exits 2 and says so"
else
  bad "symlink: --bogus through a symlinked path exited $rc (0 means the CLI never ran)"; cat "$OUT"
fi
d="$(fresh symlink-drift)"
rm "$d/docs/site/lab-manifest/zzz-from-b.json"
rc=0; node "$TOOL_VIA_LINK" --check --repo "$d" >"$OUT" 2>&1 || rc=$?
if [[ "$rc" == "1" ]] && grep -Fq 'carries "zzz-from-b" but no fragment' "$OUT"; then
  ok "symlink: --check through a symlinked path exits 1 and names the drift"
else
  bad "symlink: --check through a symlinked path exited $rc without naming zzz-from-b"; cat "$OUT"
fi

# --check must never write. Snapshot every file (path + bytes) before and after.
snapshot() { # <repo> -> digest
  node -e '
    const fs = require("fs"), path = require("path"), crypto = require("crypto");
    const h = crypto.createHash("sha256");
    const walk = (d) => { for (const f of fs.readdirSync(d).sort()) { const p = path.join(d, f);
      if (fs.statSync(p).isDirectory()) walk(p); else { h.update(p); h.update(fs.readFileSync(p)); } } };
    walk(path.join(process.argv[1], "docs")); console.log(h.digest("hex"));
  ' "$1"
}
d="$(fresh readonly)"
before="$(snapshot "$d")"
if check "$d"; then :; fi  # the verdict is not the point here, only the bytes
after="$(snapshot "$d")"
if [[ "$before" == "$after" ]]; then ok "readonly: --check wrote nothing"; else bad "readonly: --check modified the tree"; fi

echo ""
echo "Checked: $CHECKED, Failed: $FAILED"
if [[ "$FAILED" -gt 0 ]]; then
  exit 1
fi
echo "PASS: Lab manifest fragments merge clean, the aggregate is build-time only, and the set oracle fails closed"
